# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено вычислением; условия сверены с текстом учебника"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_10_1_9_68", r"в системе а) из $f>g$, $f\le1$ следует $g<1$, а из $g\ge-1$ следует $f>-1$; в системе б) из $f<g$, $g\le1$ следует $f<1$, а из $f\ge-1$ следует $g>-1$; прежний ключ («$x\ge0$», «$y\ge\sqrt x$») не относился к заданию 9.67",
  k=r"В системе а) можно опустить $g(x)\le1$ и $f(x)\ge-1$ (остаётся $-1\le g(x)<f(x)\le1$); в системе б) можно опустить $f(x)\le1$ и $g(x)\ge-1$ (остаётся $-1\le f(x)<g(x)\le1$): эти неравенства следуют из остальных",
  dnew={0: ("Ни одно неравенство опустить нельзя: без ограничений на $f(x)$ и $g(x)$ арксинус и арккосинус не определены", "Ученик не заметил, что цепочка $-1\\le g(x)<f(x)\\le1$ (в системе б) $-1\\le f(x)<g(x)\\le1$) уже задаёт область определения обеих функций, поэтому два из четырёх ограничений лишние."),
        1: (r"В обеих системах можно опустить строгое неравенство между $f(x)$ и $g(x)$", "Ученик решил, что сравнение $f$ и $g$ следует из области определения; но именно оно задаёт знак неравенства для арксинусов (арккосинусов), опустить его нельзя."),
        2: (r"В обеих системах можно опустить оба ограничения на $g(x)$ и оставить только $-1\le f(x)\le1$", "Ученик заметил, что верхняя граница для $g$ следует из $f>g$ и $f\le1$, но нижняя $g\\ge-1$ не следует из остальных: при $f=0$, $g=-2$ остальные условия выполнены, а $\\arcsin g$ не определён.")})
E("G11_TB_10_3*_10_7_б", r"$\sqrt{x-1}=x-4$, $x\ge4$: $x-1=x^{2}-8x+16 \Rightarrow x^{2}-9x+17=0$, $x=\frac{9\pm\sqrt{13}}{2}$; корень $\frac{9+\sqrt{13}}{2}\approx6{,}3\ge4$ подходит (проверка: $\sqrt{5{,}3}\approx2{,}3=6{,}3-4$), в ключе стояло «нет решений»",
  k=r"$\dfrac{9+\sqrt{13}}{2}$",
  dnew={0: (r"$x = 5$", "Ученик подобрал корень подстановкой, а не решил $x^{2}-9x+17=0$; при $x=5$ имеем $\\sqrt{4}=2\\ne1=x-4$."),
        1: (r"$x = 2$", "Ученик взял меньший корень $\\frac{9-\\sqrt{13}}{2}\\approx2{,}7$ и округлил его; этот корень не подходит и по условию $x-4\\ge0$."),
        2: (r"$x = 1$", "Ученик нашёл только нуль подкоренного выражения: при $x=1$ левая часть равна $0$, а правая $-3$.")})
